"""Emission compliance tests for app_shell (auto-generated by pact)."""

from app_shell.app_shell import AppShell


class TestEmissionCompliance:
    """Verify app_shell emits structured events correctly."""

    def _make_handler(self):
        events = []
        return events, lambda event: events.append(event)

    def test_createConvexClient_emits_events(self):
        """Method createConvexClient emits invoked and completed events."""
        events, handler = self._make_handler()
        obj = AppShell(event_handler=handler)
        try:
            obj.createConvexClient()
        except (TypeError, Exception):
            pass
        invoked = [e for e in events if e.get("event") == "invoked"]
        completed = [e for e in events if e.get("event") in ("completed", "error")]
        assert len(invoked) >= 1, 'No invoked event for createConvexClient'
        assert len(completed) >= 1, 'No completed/error event for createConvexClient'
        assert invoked[0].get("pact_key") == "PACT:app_shell:createConvexClient"
        assert isinstance(invoked[0].get("input_classification"), list)

