    def test_pact_key_format(self):
        """All emitted events have correctly formatted PACT keys."""
        events, handler = self._make_handler()
        obj = AppShell(event_handler=handler)
        try:
            obj.createConvexClient()
        except (TypeError, Exception):
            pass
        try:
            obj.isValidToolSlug()
        except (TypeError, Exception):
            pass
        try:
            obj.toolPath()
        except (TypeError, Exception):
            pass
        try:
            obj.renderApp()
        except (TypeError, Exception):
            pass
        try:
            obj.renderLayout()
        except (TypeError, Exception):
            pass
        try:
            obj.renderSidebar()
        except (TypeError, Exception):
            pass
        try:
            obj.projectToolDefToSidebarItem()
        except (TypeError, Exception):
            pass
        for event in events:
            key = event.get("pact_key", "")
            assert key.startswith("PACT:app_shell:"), f"Bad pact_key: {key}"

